    'destituido' => ["Destituído", "Dismissed", "Destituido", "Destitué"],
    'destituir' => ["Destituir", "Dismiss", "Destituir", "Destituer"],
    'destituir_diretor' => ["Destituir o diretor", "Dismiss the principal", "Destituir al director", "Destituer le directeur"],
    'data_destituicao' => ["Data da destituição", "Date of dismissal", "Fecha de destitución", "Date de destitution"],
    'ajuda_destituir' => ["A conta fica desativada e perde o acesso, mas o registo, a data e o motivo ficam guardados no histórico. Depois pode nomear outro diretor.", "The account is deactivated and loses access, but the record, date and reason stay in the history. You can then appoint another principal.", "La cuenta queda desactivada y pierde el acceso, pero el registro, la fecha y el motivo quedan en el historial. Después puede nombrar a otro director.", "Le compte est désactivé et perd l'accès, mais le dossier, la date et le motif restent dans l'historique. Vous pouvez ensuite nommer un autre directeur."],
    'confirmar_destituir' => ["Destituir este diretor? Perde o acesso de imediato.", "Dismiss this principal? Access is lost immediately.", "¿Destituir a este director? Pierde el acceso de inmediato.", "Destituer ce directeur ? L'accès est perdu immédiatement."],
    'motivo_curto' => ["Explique o motivo (pelo menos 8 caracteres).", "Explain the reason (at least 8 characters).", "Explique el motivo (al menos 8 caracteres).", "Expliquez le motif (au moins 8 caractères)."],
    'diretor_destituido' => ["%s foi destituído(a). O histórico foi atualizado.", "%s was dismissed. The history was updated.", "%s fue destituido(a). Se actualizó el historial.", "%s a été destitué(e). L'historique a été mis à jour."],
    'nomear_diretor' => ["Nomear novo diretor", "Appoint a new principal", "Nombrar nuevo director", "Nommer un nouveau directeur"],
