    'data_inicio' => ["Data de início", "Start date", "Fecha de inicio", "Date de début"],
    'diretor_nomeado' => ["%s foi nomeado(a) diretor(a).", "%s was appointed principal.", "%s fue nombrado(a) director(a).", "%s a été nommé(e) directeur(trice)."],
    'ja_existe_direcao' => ["Já há um diretor em funções. Destitua-o primeiro para nomear outro.", "There is already a principal in office. Dismiss them first to appoint another.", "Ya hay un director en funciones. Destitúyalo primero para nombrar a otro.", "Il y a déjà un directeur en fonction. Destituez-le d'abord pour en nommer un autre."],
    'ja_existe_direcao_info' => ["%s está em funções. Para nomear outro diretor, destitua-o primeiro.", "%s is in office. To appoint another principal, dismiss them first.", "%s está en funciones. Para nombrar a otro director, destitúyalo primero.", "%s est en fonction. Pour nommer un autre directeur, destituez-le d'abord."],
    'editar_diretor' => ["Editar dados do diretor", "Edit principal's details", "Editar datos del director", "Modifier les données du directeur"],
    'edicao_destituido' => ["Este diretor está destituído: pode corrigir os dados do registo, mas a conta continua desativada.", "This principal has been dismissed: you can correct the record, but the account stays deactivated.", "Este director está destituido: puede corregir los datos del registro, pero la cuenta sigue desactivada.", "Ce directeur est destitué : vous pouvez corriger le dossier, mais le compte reste désactivé."],
    'dados_alterados' => ["Dados alterados", "Details changed", "Datos modificados", "Données modifiées"],
    'nota_sem_apagar' => ["Não se apaga um diretor: destitui-se, e o histórico mantém-se, porque avisos, recibos e registos dependem dele. Pode sempre corrigir os dados.", "A principal is never deleted: they are dismissed and the history is kept, because notices, receipts and records depend on them. You can always correct the details.", "No se borra a un director: se le destituye y el historial se mantiene, porque avisos, recibos y registros dependen de él. Siempre puede corregir los datos.", "On ne supprime pas un directeur : on le destitue et l'historique est conservé, car annonces, reçus et dossiers en dépendent. Vous pouvez toujours corriger les données."],
    'historico_direcao' => ["Histórico da direção", "Principals' history", "Historial de la dirección", "Historique de la direction"],
    'historico_recente' => ["Histórico recente da direção", "Recent principals' history", "Historial reciente de la dirección", "Historique récent de la direction"],
    'hist_nomeacao' => ["Nomeação", "Appointment", "Nombramiento", "Nomination"],
    'hist_destituicao' => ["Destituição", "Dismissal", "Destitución", "Destitution"],
    'hist_edicao' => ["Edição de dados", "Data edit", "Edición de datos", "Modification des données"],
    'registado_por' => ["Registado por", "Recorded by", "Registrado por", "Enregistré par"],
    'sem_direcao_aviso' => ["Neste momento a escola não tem diretor em funções. Nomeie um novo diretor na página Conselho Geral.", "The school currently has no principal in office. Appoint one on the General Council page.", "El colegio no tiene ahora director en funciones. Nombre uno en la página Consejo General.", "L'école n'a actuellement aucun directeur en fonction. Nommez-en un dans la page Conseil général."],
    'demo_conta_inativa' => ["Esta conta de demonstração está desativada (o diretor foi destituído). Entre como Conselho Geral e nomeie um diretor ou reponha a demonstração.", "This demo account is deactivated (the principal was dismissed). Sign in as General Council and appoint a principal or reset the demo.", "Esta cuenta de demostración está desactivada (el director fue destituido). Entre como Consejo General y nombre a un director o restablezca la demostración.", "Ce compte de démonstration est désactivé (le directeur a été destitué). Connectez-vous comme Conseil général et nommez un directeur ou réinitialisez la démonstration."],

