    'apagar_registo' => ["Apagar registo", "Delete record", "Borrar registro", "Supprimer l'enregistrement"],
    'aviso_apagar_registo' => ["Use só para dados errados. O registo desaparece das contas, mas fica guardado no registo de alterações com a sua justificação.", "Use only for wrong data. The record disappears from the accounts but stays in the change log with your reason.", "Úselo solo para datos erróneos. El registro desaparece de las cuentas, pero queda en el registro de cambios con su justificación.", "À utiliser seulement pour des données erronées. L'enregistrement disparaît des comptes mais reste dans le journal avec votre justification."],
    'justificacao' => ["Justificação (obrigatória)", "Reason (required)", "Justificación (obligatoria)", "Justification (obligatoire)"],
    'justificacao_exemplo' => ["Ex.: valor lançado por engano, fatura duplicada…", "E.g. entered by mistake, duplicate invoice…", "Ej.: valor registrado por error, factura duplicada…", "Ex. : saisi par erreur, facture en double…"],
