    'motivo_alteracao' => ["Motivo da alteração", "Reason for the change", "Motivo del cambio", "Motif de la modification"],
    'aviso_editar_pago' => ["Esta propina ou este salário já foi pago. A correção fica no registo de alterações e exige justificação.", "This item has already been paid. The correction is logged and needs a reason.", "Ya está pagado. La corrección queda en el registro de cambios y exige justificación.", "Ce paiement a déjà été effectué. La correction est journalisée et exige une justification."],
    'aviso_apagar_propina' => ["Apaga a propina (e o pagamento, se existir). O recibo deixa de existir. Fica tudo guardado no registo de alterações.", "Deletes the tuition fee (and its payment, if any). The receipt no longer exists. Everything is kept in the change log.", "Borra la mensualidad (y el pago, si existe). El recibo deja de existir. Todo queda en el registro de cambios.", "Supprime la scolarité (et son paiement, s'il existe). Le reçu n'existe plus. Tout reste dans le journal."],
    'aviso_anular_pagamento' => ["O pagamento volta a «por pagar» e o recibo deixa de estar disponível. Fica no registo de alterações.", "The payment goes back to “unpaid” and the receipt is no longer available. It is kept in the change log.", "El pago vuelve a «por pagar» y el recibo deja de estar disponible. Queda en el registro de cambios.", "Le paiement redevient « à payer » et le reçu n'est plus disponible. C'est conservé dans le journal."],
    'aviso_apagar_salario' => ["Apaga o recibo de vencimento (mesmo pago). Fica guardado no registo de alterações.", "Deletes the payslip (even if paid). It is kept in the change log.", "Borra el recibo de sueldo (incluso pagado). Queda en el registro de cambios.", "Supprime la fiche de paie (même payée). C'est conservé dans le journal."],
